  opaque type Orders = Vector[Order]      // outside: abstract, no Vector ops
  val Empty: Orders = Vector.empty

  extension (orders: Orders)
    def add(order: Order): Either[OrderError, Orders] =
      if orders.length >= MaxOrders then Left(OrderError.Full)
      else Right(orders :+ order)
    def total: Money = orders.foldLeft(Money.Zero)(_ + _.amount)

final class Orders private (private val xs: Vector[Order]) extends IndexedSeq[Order] {
  override def apply(i: Int): Order = xs(i)
  override def length: Int = xs.length
  def add(order: Order): Orders =
    if (xs.length >= MaxOrders) throw OrderLimitReached
    else new Orders(xs :+ order)
}
object Orders { def apply(xs: Order*): Orders = new Orders(xs.toVector) }

